# Connect Vercel AI SDK to the AI Gateway

Send requests from your Vercel AI SDK application through the Logfire AI Gateway.

The [Vercel AI SDK](https://ai-sdk.dev/) is a TypeScript toolkit for AI web applications, including streaming, tool use, and multiple model providers. The example creates an OpenAI provider that uses an OpenAI-compatible gateway route.

## Before you start

- Complete the [AI Gateway prerequisites](index.md#before-you-start), including setting `LOGFIRE_GATEWAY_API_KEY` in your terminal.
- Use an existing Vercel AI SDK project with the packages imported below installed.

!!! note "Model data passes through Logfire"
    This configuration sends prompts, tool inputs, and model responses through the Logfire AI Gateway and the selected model provider. If gateway telemetry is enabled, Logfire stores the conversation content in your selected project. Calls to built-in providers count toward your gateway spend.

## Configure Vercel AI SDK

Set `apiKey` to your gateway key and `baseURL` to the OpenAI-compatible gateway route. Copy the route and a supported model name from the Gateway **Connect** tab.

```typescript title="vercel-ai-sdk-gateway.mts" hl_lines="12-13" skip-run="true" skip-reason="external-connection"
import { createOpenAI } from '@ai-sdk/openai';
import { generateText, stepCountIs, tool } from 'ai';
import { z } from 'zod';

const envSchema = z.object({
  LOGFIRE_GATEWAY_API_KEY: z.string(),
});

const env = envSchema.parse(process.env);

const gateway = createOpenAI({
  apiKey: env.LOGFIRE_GATEWAY_API_KEY,
  baseURL: 'https://gateway-us.pydantic.dev/proxy/openai',
});

const weatherTool = tool({
  description: 'Get the weather in a location',
  inputSchema: z.object({ location: z.string().describe('City name') }),
  outputSchema: z.object({ output: z.string() }),
  execute: async ({ location }) => ({ output: `The weather in ${location} is sunny` }),
});

const { text } = await generateText({
  model: gateway('gpt-5.4-mini'),
  prompt: 'What is the weather in London?',
  tools: { weatherTool },
  stopWhen: stepCountIs(5),
});

console.log(text);
```

## Verify it worked

Run the example from your terminal. It prints the model response. That confirms the client reached the gateway. Organization admins can also open **AI Engineering** > **Gateway** > **Spending** to see usage for the key. If telemetry is enabled, open the selected project's **Live** view to inspect the request trace.

## Troubleshooting

- **The example cannot read `LOGFIRE_GATEWAY_API_KEY`:** set the environment variable in the same terminal where you run the example.
- **The request returns an authentication or model error:** copy the URL and model name again from the Gateway **Connect** tab, and confirm that the selected route supports the OpenAI request format.

"""Verify distribution ownership and behavior throughout a v6 upgrade."""

import sqlite3
import sys
from importlib import metadata
from pathlib import Path


def distribution_version(name: str) -> str | None:
    """Return an installed distribution's version, or `None` when absent."""
    try:
        return metadata.version(name)
    except metadata.PackageNotFoundError:
        return None


def console_scripts(name: str) -> set[str]:
    """Return every target registered for a console-script name."""
    return {
        entry_point.value for entry_point in metadata.entry_points(group='console_scripts') if entry_point.name == name
    }


def assert_legacy(expected_version: str) -> None:
    """Check the monolithic distribution before the upgrade."""
    import logfire

    assert logfire.VERSION == expected_version
    assert distribution_version('logfire') == expected_version
    assert distribution_version('logfire-sdk') is None
    assert distribution_version('logfire-cli') is None
    assert console_scripts('logfire') == {'logfire.cli:main'}
    assert console_scripts('logfire-cli') == set()


def assert_sdk(expected_version: str, *, meta: bool, cli: bool) -> None:
    """Check the split SDK's behavior and ownership in the requested state."""
    import logfire

    assert logfire.VERSION == expected_version
    assert distribution_version('logfire') == (expected_version if meta else None)
    assert distribution_version('logfire-sdk') == expected_version
    assert (distribution_version('logfire-cli') is not None) is cli
    assert distribution_version('opentelemetry-instrumentation-sqlite3') is not None
    # The `logfire` meta-package owns the `logfire` command and logfire-cli owns only `logfire-cli`.
    assert console_scripts('logfire') == ({'logfire_cli:main'} if meta else set())
    assert console_scripts('logfire-cli') == ({'logfire_cli:main'} if cli else set())

    if meta:
        meta_files = metadata.files('logfire')
        assert meta_files is not None
        assert not any(str(path).startswith(('_logfire_sdk/', 'logfire/')) for path in meta_files)

    sdk_distribution = metadata.distribution('logfire-sdk')
    sdk_files = sdk_distribution.files
    assert sdk_files is not None
    assert '_logfire_sdk/logfire/__init__.py' in {path.as_posix() for path in sdk_files}
    package_inits = {
        sdk_distribution.locate_file(path).resolve()
        for path in sdk_files
        if path.as_posix().endswith('logfire/__init__.py')
    }
    assert Path(logfire.__file__).resolve() in package_inits

    logfire.configure(send_to_logfire=False)
    logfire.instrument_sqlite3()
    with logfire.span('split-package lifecycle works'):
        logfire.info('imported from logfire-sdk')
        with sqlite3.connect(':memory:') as connection:
            assert connection.execute('SELECT 1').fetchone() == (1,)
    assert logfire.force_flush()
    assert logfire.shutdown()


def main() -> None:
    """Run the assertions for the expected major version."""
    state, expected_version = sys.argv[1:]
    if state == 'legacy':
        assert_legacy(expected_version)
    elif state == 'split':
        assert_sdk(expected_version, meta=True, cli=True)
    elif state == 'sdk-and-cli':
        assert_sdk(expected_version, meta=False, cli=True)
    elif state == 'sdk-only':
        assert_sdk(expected_version, meta=False, cli=False)
    else:
        raise AssertionError(f'Unsupported upgrade-test state: {state}')


if __name__ == '__main__':
    main()

from __future__ import annotations

from collections.abc import Callable
from importlib import import_module, metadata, util


def assert_not_available(package: str) -> None:
    """Assert that a package is neither installed nor importable."""
    if util.find_spec(package) is not None:
        raise AssertionError(f'{package} should not be importable')

    try:
        metadata.version(package)
    except metadata.PackageNotFoundError:
        pass
    else:
        raise AssertionError(f'{package} should not be installed')


def assert_distribution_not_installed(distribution: str) -> None:
    """Assert that an installable distribution is absent."""
    try:
        metadata.version(distribution)
    except metadata.PackageNotFoundError:
        return
    raise AssertionError(f'{distribution} should not be installed')


def assert_import_error(label: str, func: Callable[[], object], expected_message: str) -> None:
    """Assert that an optional feature fails without its extra dependencies."""
    try:
        func()
    except ImportError as exc:
        if expected_message not in str(exc):
            raise AssertionError(f'{label} raised an unexpected error message: {exc}') from exc
    else:
        raise AssertionError(f'{label} should fail without its extra dependencies')


class NotJsonSerializable:
    """A simple object for exercising non-JSON attribute handling."""


def main() -> None:
    """Smoke-test core logfire APIs in a minimal installation."""
    optional_packages = ('pytest', 'pydantic', 'pydantic_handlebars', 'httpx')

    for package in optional_packages:
        assert_not_available(package)

    import logfire

    assert_distribution_not_installed('logfire')
    assert_distribution_not_installed('logfire-cli')
    if any(entry_point.name == 'logfire' for entry_point in metadata.entry_points(group='console_scripts')):
        raise AssertionError('The SDK-only install should not provide the Logfire CLI')

    sdk_files = metadata.files('logfire-sdk')
    if sdk_files is None:
        raise AssertionError('The SDK distribution has no file manifest')
    for package_init in ('logfire/__init__.py', '_logfire_sdk/logfire/__init__.py'):
        if not any(str(path) == package_init for path in sdk_files):
            raise AssertionError(f'The SDK distribution is missing {package_init}')

    for package in optional_packages:
        assert_not_available(package)

    assert_import_error('testing helpers', lambda: import_module('logfire.testing'), "No module named 'pytest'")
    assert_import_error(
        'query client',
        lambda: import_module('logfire.query_client'),
        'httpx is required to use the Logfire query clients',
    )
    assert_import_error(
        'datasets client',
        lambda: import_module('logfire.experimental.api_client'),
        "No module named 'pydantic'",
    )
    assert_import_error(
        'managed variable imports',
        lambda: getattr(import_module('logfire.variables'), 'Variable'),
        'Using managed variables requires the `pydantic_handlebars` and `pydantic` packages',
    )
    assert_import_error(
        'managed variable usage',
        lambda: logfire.var('minimal_install_flag', default=False),
        'Using managed variables requires the `pydantic_handlebars` and `pydantic` packages',
    )

    for package in optional_packages:
        assert_not_available(package)

    logfire.configure(send_to_logfire=False)
    not_json_serializable = NotJsonSerializable()
    logfire.info('minimal install info', answer=42, not_json_serializable=not_json_serializable)
    with logfire.span('minimal install span', answer=42, not_json_serializable=not_json_serializable):
        logfire.debug('inside minimal install span')

    counter = logfire.metric_counter('minimal_install_counter')
    counter.add(1)
    assert logfire.force_flush()
    assert logfire.shutdown()


if __name__ == '__main__':
    main()

